def count_running_jitsi_calls(apps, schema_editor):
    """
    Treat people already in a Jitsi room at deploy time as admitted, so calls that
    are running when this ships count toward the room limit. Views older than the
    stale-view cleanup window (6 hours) are left alone.
    """
    RoomView = apps.get_model("base", "RoomView")
    RoomView.objects.filter(
        end__isnull=True,
        start__gte=now() - timedelta(hours=6),
        room__module_config__contains=[{"type": "call.jitsi"}],
    ).update(jitsi_joined_at=F("start"))


